<?php
$uid = (int)$u['id'];
handle('rule_add', function () use ($uid) { Rules::create($uid, $_POST); return 'Rule created.'; });
handle('rule_status', function () use ($uid) { $to = $_POST['to'] === 'paused' ? 'paused' : 'active'; q('UPDATE money_rules SET status=?, fail_count=0 WHERE id=? AND user_id=?', [$to, (int)$_POST['id'], $uid]); return 'Rule ' . $to . '.'; });
handle('rule_delete', function () use ($uid) { q('DELETE FROM money_rules WHERE id=? AND user_id=?', [(int)$_POST['id'], $uid]); return 'Rule deleted.'; });
handle('rule_run', function () use ($uid) { $r = Rules::runDue($uid); return "Ran due rules: {$r['ok']} executed, {$r['failed']} failed, {$r['skipped']} skipped (already run for that date)."; });
echo page_head('Money rules', 'Automations that run exactly once per trigger. Every run is logged, and failures stop after three tries.', form_start('rule_run', 'class="inline"') . btn('Run due rules now', 'secondary sm') . '</form>');
$pk = array_column(rows('SELECT id, name FROM pockets WHERE user_id=?', [$uid]), 'name', 'id'); $rs = rows('SELECT r.*, u.name AS tname, p.name AS pname FROM money_rules r LEFT JOIN users u ON u.id=r.target_user_id LEFT JOIN pockets p ON p.id=r.target_pocket_id WHERE r.user_id=? ORDER BY r.id DESC', [$uid]); $rows = [];
foreach ($rs as $r) { $d = match ($r['rule_type']) { 'scheduled_transfer' => 'Send ' . money($r['amount']) . ' to ' . $r['tname'] . ' ' . $r['frequency'] . ', next ' . $r['next_run'], 'income_allocation' => $r['percent'] . '% of each income to ' . $r['pname'], 'round_up' => 'Round purchases up to the next ' . $r['round_to'] . ' and save the change in ' . $r['pname'], default => 'Alert when balance drops below ' . money($r['threshold']) };
  $rows[] = [e($r['name']), e($d), badge($r['status']), '<span class="hint">' . e($r['last_message'] ?: '-') . '</span>', form_start('rule_status', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$r['id'] . '"><input type="hidden" name="to" value="' . ($r['status'] === 'active' ? 'paused' : 'active') . '">' . btn($r['status'] === 'active' ? 'Pause' : 'Enable', 'secondary sm') . '</form> ' . form_start('rule_delete', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$r['id'] . '">' . btn('Delete', 'secondary sm', 'submit', 'onclick="return confirm(\'Delete rule?\')"') . '</form>']; }
$logs = rows('SELECT l.*, r.name FROM rule_runs l JOIN money_rules r ON r.id=l.rule_id WHERE r.user_id=? ORDER BY l.id DESC LIMIT 12', [$uid]); $lr = [];
foreach ($logs as $l) $lr[] = [e(fdate($l['ran_at'])), e($l['name']), badge($l['status']), e($l['message']), $l['txn_id'] ? ref_link((string)val('SELECT ref FROM transactions WHERE id=?', [$l['txn_id']])) : ''];
echo card('Your rules', tbl(['Name', 'What it does', 'Status', 'Last result', ''], $rows, 'No rules yet.')) . '<div style="height:16px"></div><div class="grid g2">' . card('Run log', tbl(['When', 'Rule', 'Result', 'Message', 'Txn'], $lr, 'Nothing has run yet.')) .
 card('Create a rule', form_start('rule_add') . select('Rule type', 'rule_type', ['scheduled_transfer' => 'Scheduled transfer', 'income_allocation' => 'Income allocation to a pocket', 'round_up' => 'Round-up saving', 'low_balance_alert' => 'Low-balance alert'], 'scheduled_transfer') . field('Name', 'name', 'text', '', 'maxlength="100"') . '<p class="hint">Fill only the fields your rule type needs.</p>' . field('Recipient (scheduled transfer)', 'target', 'text', '', 'placeholder="email or phone"') . '<div class="row">' . field('Amount', 'amount', 'text', '', 'inputmode="decimal"') . select('Frequency', 'frequency', ['weekly' => 'Weekly', 'monthly' => 'Monthly', 'daily' => 'Daily'], 'monthly') . field('First run', 'next_run', 'date', date('Y-m-d', strtotime('+1 day'))) . '</div>' . select('Pocket (allocation / round-up)', 'pocket', ['' => '-'] + $pk) . '<div class="row">' . field('Percent of income', 'percent', 'text', '', 'inputmode="decimal" placeholder="10"') . select('Round up to', 'round_to', ['10' => '10', '5' => '5', '50' => '50', '100' => '100'], '10') . field('Alert below', 'threshold', 'text', '', 'inputmode="decimal"') . '</div>' . btn('Create rule') . '</form>') . '</div>';
